import{_ as e,o as d,c as a,a2 as s}from"./chunks/framework.Ch4PdLd_.js";const k=JSON.parse('{"title":"会话与上下文","description":"","frontmatter":{},"headers":[],"relativePath":"guide/sessions.md","filePath":"guide/sessions.md"}'),o={name:"guide/sessions.md"};function i(c,t,n,r,l,h){return d(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="会话与上下文" tabindex="-1">会话与上下文 <a class="header-anchor" href="#会话与上下文" aria-label="Permalink to &quot;会话与上下文&quot;">​</a></h1><p>nek 把一段对话保存为一个<strong>会话</strong>。会话里的消息组成一棵树，当前所在的那条路径（<strong>活动分支</strong>）就是下一次请求发给模型的历史。这一页讲怎么续接会话、怎么分支尝试另一种做法，以及怎么控制发给模型的上下文大小。</p><h2 id="续接与切换会话" tabindex="-1">续接与切换会话 <a class="header-anchor" href="#续接与切换会话" aria-label="Permalink to &quot;续接与切换会话&quot;">​</a></h2><p>会话默认自动保存（用 <code>--no-session</code> 启动时除外）。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # --continue：继续当前目录最近的会话</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # --resume：打开会话列表选择</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;上次说到哪了？&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 继续并立即发送一条消息</span></span></code></pre></div><p>在 nek 里：</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/resume</code></td><td>打开会话列表，切换到别的会话</td></tr><tr><td><code>/new</code></td><td>开始新会话</td></tr><tr><td><code>/name &lt;名字&gt;</code></td><td>设置会话显示名（不带参数时显示当前名字）。也可以启动时用 <code>-n &quot;名字&quot;</code></td></tr><tr><td><code>/session</code></td><td>查看会话文件路径、ID、消息数、token 用量和费用</td></tr></tbody></table><h3 id="会话列表" tabindex="-1">会话列表 <a class="header-anchor" href="#会话列表" aria-label="Permalink to &quot;会话列表&quot;">​</a></h3><p><code>/resume</code> 和 <code>nek -r</code> 打开的列表支持搜索，以及这些快捷键：</p><table tabindex="0"><thead><tr><th>按键</th><th>作用</th></tr></thead><tbody><tr><td>输入文字</td><td>搜索</td></tr><tr><td><code>Ctrl+P</code></td><td>显示/隐藏会话所在路径</td></tr><tr><td><code>Ctrl+S</code></td><td>切换排序方式</td></tr><tr><td><code>Ctrl+N</code></td><td>只看起过名字的会话</td></tr><tr><td><code>Ctrl+R</code></td><td>重命名选中的会话</td></tr><tr><td><code>Ctrl+D</code></td><td>删除选中的会话（需确认；有 <code>trash</code> 命令时移到回收站）</td></tr><tr><td><code>Ctrl+Backspace</code></td><td>搜索框为空时删除选中的会话</td></tr></tbody></table><h3 id="按路径或-id-打开" tabindex="-1">按路径或 ID 打开 <a class="header-anchor" href="#按路径或-id-打开" aria-label="Permalink to &quot;按路径或 ID 打开&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">路径或I</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 按文件路径、完整 ID 或 ID 前缀打开</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session-id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-task</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 打开当前项目里 ID 为 my-task 的会话，不存在就创建</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fork</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">路径或I</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 把已有会话复制成当前项目的一个新会话</span></span></code></pre></div><p><code>--session</code> 先在当前项目里查找；匹配到其他项目的会话时，会提示你复制（fork）一份到当前项目。会话 ID 只能包含字母、数字、<code>.</code>、<code>_</code>、<code>-</code>，且首尾必须是字母或数字。</p><h2 id="branching" tabindex="-1">分支：换一条路线试试 <a class="header-anchor" href="#branching" aria-label="Permalink to &quot;分支：换一条路线试试 {#branching}&quot;">​</a></h2><p>会话以树的形式存储，回到较早的某一点继续，不会抹掉你离开的那条分支。</p><table tabindex="0"><thead><tr><th>操作</th><th>结果</th><th>适合</th></tr></thead><tbody><tr><td><code>/tree</code></td><td>在当前会话内移动到任意一个节点，从那里继续</td><td>相关的多种尝试放在一起</td></tr><tr><td><code>/fork</code></td><td>选一条较早的用户消息，从它开始创建一个新会话</td><td>另一种做法应该成为独立的工作</td></tr><tr><td><code>/clone</code></td><td>把当前活动分支原样复制成一个新会话</td><td>想要一份当前状态的独立副本</td></tr></tbody></table><p>输入框为空时连按两次 <code>Escape</code>，默认打开 <code>/tree</code>（设置 <code>doubleEscapeAction</code> 可改为 <code>fork</code> 或 <code>none</code>）。</p><h3 id="会话树-tree" tabindex="-1">会话树 <code>/tree</code> <a class="header-anchor" href="#会话树-tree" aria-label="Permalink to &quot;会话树 \`/tree\`&quot;">​</a></h3><p><code>/tree</code> 以树状显示整个会话，选中一个节点后按 <code>Enter</code> 跳过去。常用按键：</p><table tabindex="0"><thead><tr><th>按键</th><th>作用</th></tr></thead><tbody><tr><td><code>Ctrl+←</code> / <code>Alt+←</code></td><td>折叠当前分支段，或跳到上一段的开头</td></tr><tr><td><code>Ctrl+→</code> / <code>Alt+→</code></td><td>展开当前分支段，或跳到下一段的开头/分支末尾</td></tr><tr><td><code>Shift+L</code></td><td>给选中的节点加标签（书签）</td></tr><tr><td><code>Shift+T</code></td><td>显示/隐藏标签的时间</td></tr><tr><td><code>Ctrl+D</code></td><td>过滤器：默认视图</td></tr><tr><td><code>Ctrl+T</code></td><td>过滤器：隐藏工具结果</td></tr><tr><td><code>Ctrl+U</code></td><td>过滤器：只看用户消息</td></tr><tr><td><code>Ctrl+L</code></td><td>过滤器：只看带标签的节点</td></tr><tr><td><code>Ctrl+A</code></td><td>过滤器：显示全部</td></tr><tr><td><code>Ctrl+O</code> / <code>Shift+Ctrl+O</code></td><td>循环切换过滤器</td></tr><tr><td><code>Ctrl+X</code></td><td>复制选中的消息</td></tr></tbody></table><p>打开时使用的默认过滤器由设置 <code>treeFilterMode</code> 决定。</p><h3 id="分支摘要" tabindex="-1">分支摘要 <a class="header-anchor" href="#分支摘要" aria-label="Permalink to &quot;分支摘要&quot;">​</a></h3><p>离开一条分支时，nek 会问你是否为它生成摘要。选择生成的话，模型会把被放弃的那条路径总结一下，附在你进入的新位置上。这样新分支能知道之前试过什么，又不用带上全部消息。</p><p>不想每次被问，可以设置 <code>branchSummary.skipPrompt: true</code>（默认不生成摘要）。</p><h2 id="compaction" tabindex="-1">控制上下文大小 <a class="header-anchor" href="#compaction" aria-label="Permalink to &quot;控制上下文大小 {#compaction}&quot;">​</a></h2><p>发给模型的只有<strong>活动分支</strong>，不是会话里的所有分支。nek 把活动分支和系统提示词、项目指令、工具声明、Skills 描述组合起来，见 <a href="/nekcode/start/how-it-works#context">nekcode 如何工作</a>。</p><p>上下文接近模型上限时，nek 会自动<strong>压缩</strong>：</p><ol><li>从最新的消息往回数，保留大约 20k token 的近期消息原样不动；</li><li>更早的部分交给模型总结成一份结构化摘要（目标、约束、进度、关键决定、下一步、关键上下文，以及读过和改过的文件）；</li><li>之后的请求用“摘要 + 近期消息”代替完整历史。</li></ol><p>原始消息仍然保存在会话里，<code>/tree</code> 和导出都能看到。</p><table tabindex="0"><thead><tr><th>操作</th><th>方式</th></tr></thead><tbody><tr><td>手动压缩</td><td><code>/compact</code>，可以附加说明，例如 <code>/compact 重点保留数据库迁移相关的结论</code></td></tr><tr><td>关闭自动压缩</td><td>设置 <code>compaction.enabled: false</code>（仍可手动压缩）</td></tr><tr><td>调整触发时机和保留量</td><td><code>compaction.reserveTokens</code>、<code>compaction.keepRecentTokens</code></td></tr><tr><td>用另一个模型写摘要</td><td><code>compaction.model</code>、<code>compaction.thinkingLevel</code></td></tr></tbody></table><p>状态栏的上下文进度条显示当前用量。压缩的触发条件、内容折叠策略和全部设置见 <a href="/nekcode/reference/compaction">上下文压缩</a>。</p><h2 id="storage" tabindex="-1">会话存储位置 <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;会话存储位置 {#storage}&quot;">​</a></h2><p>默认存放在 <code>~/.nek/agent/sessions/</code> 下，按工作目录分组：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.nek/agent/sessions/--home-me-project--/2026-10-16T08-00-00-000Z_&lt;会话ID&gt;.sqlite</span></span>
<span class="line"><span>~/.nek/agent/sessions/--home-me-project--/2026-10-16T08-00-00-000Z_&lt;会话ID&gt;.meta.json</span></span></code></pre></div><ul><li><code>.sqlite</code> 是会话数据库；<code>.meta.json</code> 只是 <code>/resume</code> 列表的缓存，丢了会自动重建；</li><li>会话打开期间旁边有一个 <code>.lock</code> 文件，同一个会话不能被两个 nek 进程同时打开；</li><li>子代理的会话存放在父会话目录下的 <code>subagents/</code> 里。</li></ul><p>改变存储位置（优先级从高到低）：</p><ol><li>启动参数 <code>--session-dir &lt;目录&gt;</code>；</li><li>环境变量 <code>NEK_CODING_AGENT_SESSION_DIR</code>；</li><li>设置 <code>sessionDir</code>（相对路径从工作目录解析）。</li></ol><p>其他相关参数：<code>--no-session</code> 使用不落盘的临时会话。</p><h3 id="崩溃后续跑" tabindex="-1">崩溃后续跑 <a class="header-anchor" href="#崩溃后续跑" aria-label="Permalink to &quot;崩溃后续跑&quot;">​</a></h3><p>一轮里的每一步都会先写入数据库再继续。nek 被强制结束（崩溃、<code>kill</code>、关掉终端、断电）后，用 <code>nek -c</code> 或 <code>/resume</code> 重新打开会话，中断的那一轮会自动接着跑。哪些工具会重跑、哪些只标记为“已中断”，见 <a href="/nekcode/reference/durable-sessions">Durable 会话与崩溃续跑</a>。</p><h3 id="旧的-jsonl-会话" tabindex="-1">旧的 JSONL 会话 <a class="header-anchor" href="#旧的-jsonl-会话" aria-label="Permalink to &quot;旧的 JSONL 会话&quot;">​</a></h3><p>从 pi 或旧版 nek 带过来的 <code>.jsonl</code> 会话可以直接打开（<code>--session &lt;路径&gt;</code>），或在 nek 里用 <code>/import &lt;路径&gt;</code> 导入。打开时 nek 会生成同名的 <code>.sqlite</code>，原来的 <code>.jsonl</code> 文件保持不变。</p><h3 id="删除会话" tabindex="-1">删除会话 <a class="header-anchor" href="#删除会话" aria-label="Permalink to &quot;删除会话&quot;">​</a></h3><p>在 <code>/resume</code> 列表里选中后按 <code>Ctrl+D</code> 并确认；或直接删除 <code>~/.nek/agent/sessions/</code> 下对应的 <code>.sqlite</code> 和 <code>.meta.json</code> 文件（以及可能存在的旧 <code>.jsonl</code> 文件）。</p><h2 id="导出与分享" tabindex="-1">导出与分享 <a class="header-anchor" href="#导出与分享" aria-label="Permalink to &quot;导出与分享&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/export [路径]</code></td><td>导出为 HTML（默认）或 JSONL（路径以 <code>.jsonl</code> 结尾）</td></tr><tr><td><code>/share</code></td><td>上传并返回查看链接（Radius，或通过 <code>gh</code> 创建私密 gist）</td></tr><tr><td><code>nek --export &lt;会话文件&gt; [输出.html]</code></td><td>在命令行导出</td></tr></tbody></table><p>导出或分享前请检查内容：会话里可能有提示词、模型回复、工具参数、命令输出、文件内容和扩展消息。</p>`,47)])])}const b=e(o,[["render",i]]);export{k as __pageData,b as default};
